            if not a[i] in ['+', '-'] or (i > 1 and a[i - 2] == '(') or (i + 2 < l and a[i + 2] == ')'):
                continue
            fl = f(a[:i])
            fr = f(a[i + 1:])
            if a[i] == '+':
                ri.append(fl[0] + fr[0])
                ra.append(fl[1] + fr[1])
            else:
                ri.append(fl[0] - fr[1])
                ra.append(fl[1] - fr[0])
        r = [min(ri), max(ra)]
        fm[key] = r
        return r
    r = f(a)
