class Part:

    def __init__(self, i):
        self.ind = i
        self.top = None
        self.und = None
        self.sta = 0
        self.rem = -1

    def prog(self, time):
        if self.top != None:
            self.top.rem -= time
        if self.und != None:
            self.und.rem -= time
        if self.sta != 0:
            self.rem -= time

    def out(self):
        if self.sta == 2:
            if self.und.rem <= 0 and self.top.rem <= 0:
                outs = [self.und.ind, self.top.ind]
                self.und = None
                self.top = None
                self.sta = 0
                self.rem = -1
                return outs
            if self.und.rem <= 0:
                outs = [self.und.ind]
                self.und = None
                self.sta = 1
                self.rem = self.top.rem
                return outs
        if self.sta == 1:
            if self.top.rem <= 0:
                outs = [self.top.ind]
                self.top = None
                self.sta = 0
                self.rem = -1
                return outs
        return []

    def into(self, rem, ind):
        if self.sta == 0:
            self.top = Car(rem, ind)
            self.sta = 1
            self.rem = rem
        elif self.sta == 1:
            self.und = Car(rem, ind)
            self.sta = 2
            self.rem = rem

