class WarshallFloyd:

    def __init__(self, e, n):
        self.E = e
        self.N = n

    def search(self):
        n = self.N
        nl = list(range(n))
        d = [[inf] * n for _ in nl]
        for k, v in self.E.items():
            for b, c in v:
                if d[k][b] > c:
                    d[k][b] = c
        for i in nl:
            for j in nl:
                if i == j:
                    continue
                for k in nl:
                    if i != k and j != k and (d[j][k] > d[j][i] + d[i][k]):
                        d[j][k] = d[j][i] + d[i][k]
                        d[j][k] = d[j][i] + d[i][k]
        return d

