N, M = map(int, input().split())
INF = float('inf')
G = [[INF] * N for i in range(N)]
for i in range(M):
    s, t, d = map(int, input().split())
    G[s][t] = d
dp = [[INF] * N for i in range(1 << N)]
dp[1][0] = 0
for bs in range(1 << N):
    for n in range(N):
        if dp[bs][n] == INF:
            continue
        for to in range(N):
            if bs & 1 << to:
                continue
            next_index = bs | 1 << to
            dp[next_index][to] = min(dp[next_index][to], dp[bs][n] + G[n][to])
ans = INF
for fr in range(1, N):
    ans = min(ans, dp[-1][fr] + G[fr][0])
print(ans if ans != INF else -1)

